// Ternary state — three possible conditions, not two
export type CrystalState = "Divergent" | "Resonant" | "Convergent";

export interface Crystal {
  readonly state:      CrystalState;
  readonly coherence:  number;   // 0.0 – 1.0
  readonly symmetry:   number;   // 0.0 – 1.0
  readonly emergence:  number;   // 0.0 – 1.0
  readonly frequency:  number;   // Hz
}

content.rust:
// État ternaire — trois conditions, pas deux
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum CrystalState {
    Divergent,   // expansion, entropie haute
    Resonant,    // stable, à fréquence
    Convergent,  // contraction, cristallisation
}

#[derive(Debug, Clone)]
pub struct Crystal {
    pub state:      CrystalState,
    pub coherence:  f64,  // 0.0 – 1.0
    pub symmetry:   f64,  // 0.0 – 1.0
    pub emergence:  f64,  // 0.0 – 1.0
    pub frequency:  f64,  // Hz
}
